uniform shader amzt_glowB;
float4 amzSample_glowB(float2 uv) { return float4(amzt_glowB.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_glowC;
float4 amzSample_glowC(float2 uv) { return float4(amzt_glowC.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
