float4 amzSample_glowD(float2 uv) { return float4(amzt_glowD.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_glowA(uv);if(tex==2) return amzSample_glowB(uv);if(tex==3) return amzSample_glowC(uv);if(tex==4) return amzSample_glowD(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_glowAmount;
uniform float amzp_glowRadius;
uniform float amzp_glowSoftness;
uniform float amzp_glowSpread;
uniform float amzp_threshold;
uniform float amzp_softKnee;
uniform float amzp_threshGamma;
uniform float amzp_hlGlowStr;
uniform float amzp_hlThreshold;
uniform float amzp_hlSaturation;
uniform float amzp_innerWeight;
uniform float amzp_outerWeight;
uniform float amzp_tailWeight;
layout(color) uniform half4 amzp_glowTint;
uniform float amzp_glowTintStr;
uniform float amzp_glowWarmth;
uniform float amzp_glowSatBoost;
uniform float amzp_colorPreserve;
uniform float amzp_halStr;
layout(color) uniform half4 amzp_halColor;
uniform float amzp_diffAmount;
uniform float amzp_diffHighlights;
uniform float amzp_filmGrain;
uniform float amzp_filmFade;
uniform float amzp_filmSaturation;
uniform float amzp_filmContrast;
uniform float amzp_filmWarmth;
uniform float amzp_softClipKnee;
uniform float amzp_blendMode;
uniform float amzp_quality;
uniform float amzp_glowOnly;
uniform float amzp_ditherAmt;
uniform float amzp_globalMix;
    float lum(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }
    float3 srgbToLinear(float3 s) {
        float3 lo = s / 12.92;
        float3 hi = pow((s + 0.055) / 1.055, float3(2.4));
        return mix(lo, hi, step(float3(0.04045), s));
    }
    float3 linearToSrgb(float3 l) {
        float3 lo = l * 12.92;
        float3 hi = 1.055 * pow(max(l, 0.0), float3(1.0 / 2.4)) - 0.055;
        return mix(lo, hi, step(float3(0.0031308), l));
    }
    float noiseHash(float2 p) {
        float3 p3 = fract(float3(p.xyx) * 0.1031);
        p3 += dot(p3, p3.yzx + 33.33);
        return fract((p3.x + p3.y) * p3.z);
    }
    float getTaps(float q) {
        if (q < 1.5) return 8.0;
        if (q < 2.5) return 14.0;
        return 20.0;
    }
    float4 blurPass(int tex, float2 texOff, float2 st, float numPx) {
        if (numPx <= 0.0) return amzTexture(tex, st);
        float sigma = numPx / 2.14596602;
        sigma = max(sigma, 0.00001);
         float3 ig;
        ig.x = 1.0 / (sqrt(2.0 * 3.14159265359) * sigma);
        ig.y = exp(-0.5 / (sigma * sigma));
        ig.z = ig.y * ig.y;
        float4 avg = amzTexture(tex, st) * ig.x;
        float cSum = ig.x;
        for (float i = 1.0; i <= 256.0; i += 2.0) {
            if (i > numPx) break;
            ig.xy *= ig.yz;
            cSum += 2.0 * ig.x;
            float w0 = ig.x;
            ig.xy *= ig.yz;
            cSum += 2.0 * ig.x;
            float w1 = ig.x;
            float wL = w0 + w1;
            float oL = (i * w0 + (i + 1.0) * w1) / max(wL, 0.00001);
            avg += amzTexture(tex, clamp(st - oL * texOff, 0.0, 1.0)) * wL;
            avg += amzTexture(tex, clamp(st + oL * texOff, 0.0, 1.0)) * wL;
        }
        return avg / max(cSum, 0.00001);
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float taps = getTaps(float(int(amzp_quality)));
        float r1 = amzp_glowRadius * 0.5;
        float r2 = amzp_glowRadius * amzp_glowSpread * 0.5;
        if (amzPass == 0) {
            float4 src = amzTexture(0, uv);
            float3 rgb = max(src.rgb, 0.0);
            float3 lin = srgbToLinear(rgb);
            float brightness = lum(lin);
            brightness = pow(max(brightness, 0.0), amzp_threshGamma);
            float knee = max(amzp_softKnee, 0.00001);
            float edge = brightness - amzp_threshold + knee;
            edge = clamp(edge / (2.0 * knee), 0.0, 1.0);
            edge *= edge;
            float mask = max(edge, max(brightness - amzp_threshold, 0.0));
            mask = mask / max(brightness, 0.00001);
            float3 extracted = rgb * mask;
            amzOutput = float4(extracted, src.a);
            return;
        }
        if (amzPass == 1) {
            float2 to = float2(1.0 / getTexSize((screen.zw/2.0)).x, 0.0);
            float ks = r1 * (taps / 10.0);
            amzOutput = blurPass(1, to, uv, ks);
            return;
        }
        if (amzPass == 2) {
            float2 to = float2(0.0, 1.0 / getTexSize((screen.zw/2.0)).y);
            float ks = r1 * (taps / 10.0);
            amzOutput = blurPass(2, to, uv, ks);
            return;
        }
        if (amzPass == 3) {
            float2 to = float2(1.0 / getTexSize((screen.zw/2.0)).x, 0.0);
            float ks = r2 * (taps / 10.0);
            amzOutput = blurPass(1, to, uv, ks);
            return;
        }
        float4 src = amzTexture(0, uv);
        float3 baseRGB = max(src.rgb, 0.0);
        float3 innerGlow = max(amzTexture(3, uv).rgb, 0.0);
        float3 outerGlow = max(amzTexture(4, uv).rgb, 0.0);
        float3 innerLin = srgbToLinear(innerGlow);
        float3 outerLin = srgbToLinear(outerGlow);
        float3 baseLin = srgbToLinear(baseRGB);
        float baseLum = lum(baseLin);
        float3 totalGlow = innerLin * amzp_innerWeight + outerLin * amzp_outerWeight * amzp_tailWeight;
        totalGlow = mix(innerLin * amzp_innerWeight, totalGlow, amzp_glowSoftness);
        if (amzp_hlGlowStr > 0.00001) {
            float hlMask = smoothstep(amzp_hlThreshold - 0.1, amzp_hlThreshold + 0.1, baseLum);
            float3 hlGlow = outerLin * hlMask;
            if (abs(amzp_hlSaturation - 1.0) > 0.00001) {
                float hlL = lum(hlGlow);
                hlGlow = mix(float3(hlL), hlGlow, amzp_hlSaturation);
            }
            totalGlow += hlGlow * amzp_hlGlowStr * 0.5;
        }
        if (amzp_colorPreserve > 0.00001) {
            float glowLum = lum(totalGlow);
            if (baseLum > 0.00001 && glowLum > 0.00001) {
                float3 baseColor = baseLin / max(baseLum, 0.00001);
                float3 coloredGlow = baseColor * glowLum;
                totalGlow = mix(totalGlow, coloredGlow, amzp_colorPreserve * 0.5);
            }
        }
        if (abs(amzp_glowSatBoost - 1.0) > 0.00001) {
            float gL = lum(totalGlow);
            totalGlow = mix(float3(gL), totalGlow, amzp_glowSatBoost);
        }
        if (abs(amzp_glowWarmth) > 0.00001) {
            float gL = lum(totalGlow);
            totalGlow.r += amzp_glowWarmth * 0.04 * gL;
            totalGlow.b -= amzp_glowWarmth * 0.03 * gL;
        }
        if (amzp_glowTintStr > 0.00001) {
            totalGlow = mix(totalGlow, totalGlow * srgbToLinear(amzp_glowTint.rgb), amzp_glowTintStr);
        }
        if (amzp_halStr > 0.00001) {
            float halLum = lum(outerLin);
            float halMask = smoothstep(0.2, 0.6, halLum);
            float3 halation = outerLin * srgbToLinear(amzp_halColor.rgb) * halMask;
            totalGlow += halation * amzp_halStr * 0.5;
        }
        if (amzp_diffAmount > 0.00001) {
            float3 diffGlow = mix(innerLin, outerLin, 0.5);
            float diffHL = smoothstep(0.3, 0.8, baseLum);
            diffGlow *= mix(1.0, diffHL, amzp_diffHighlights);
            totalGlow += diffGlow * amzp_diffAmount * 0.3;
        }
        totalGlow *= amzp_glowAmount;
        totalGlow = 1.0 - exp(-totalGlow * amzp_softClipKnee);
        float3 glowSRGB = linearToSrgb(max(totalGlow, 0.0));
        if ((amzp_glowOnly>0.5)) {
            amzOutput = float4(clamp(glowSRGB, 0.0, 1.0), 1.0);
            return;
        }
        float3 comp;
        float bm = float(int(amzp_blendMode));
        if (bm < 1.5) {
            comp = baseLin + srgbToLinear(max(glowSRGB, 0.0));
        } else if (bm < 2.5) {
            comp = srgbToLinear(1.0 - (1.0 - baseRGB) * (1.0 - clamp(glowSRGB, 0.0, 1.0)));
        } else if (bm < 3.5) {
            float3 gC = clamp(glowSRGB, 0.0, 1.0);
            float3 r;
            r.r = (gC.r<0.5) ? 2.0*baseRGB.r*gC.r+baseRGB.r*baseRGB.r*(1.0-2.0*gC.r) : 2.0*baseRGB.r*(1.0-gC.r)+sqrt(max(baseRGB.r,0.0))*(2.0*gC.r-1.0);
            r.g = (gC.g<0.5) ? 2.0*baseRGB.g*gC.g+baseRGB.g*baseRGB.g*(1.0-2.0*gC.g) : 2.0*baseRGB.g*(1.0-gC.g)+sqrt(max(baseRGB.g,0.0))*(2.0*gC.g-1.0);
            r.b = (gC.b<0.5) ? 2.0*baseRGB.b*gC.b+baseRGB.b*baseRGB.b*(1.0-2.0*gC.b) : 2.0*baseRGB.b*(1.0-gC.b)+sqrt(max(baseRGB.b,0.0))*(2.0*gC.b-1.0);
            comp = srgbToLinear(r);
        } else {
            comp = max(baseLin, srgbToLinear(max(glowSRGB, 0.0)));
        }
        float3 fin = linearToSrgb(max(comp, 0.0));
        if (abs(amzp_filmSaturation - 1.0) > 0.00001) {
            float fl = lum(fin);
            fin = mix(float3(fl), fin, amzp_filmSaturation);
        }
        if (abs(amzp_filmContrast) > 0.5) {
            float fc = amzp_filmContrast / 100.0;
            float fl = lum(fin);
            float sCurve = fl + fc * 0.5 * (fl - 0.5) * (1.0 - abs(fl - 0.5) * 2.0);
            float ratio = sCurve / max(fl, 0.00001);
            fin *= ratio;
        }
        if (abs(amzp_filmWarmth) > 0.00001) {
            fin.r += amzp_filmWarmth * 0.06;
            fin.b -= amzp_filmWarmth * 0.04;
        }
        if (amzp_filmFade > 0.00001) {
            fin = fin * (1.0 - amzp_filmFade * 0.15) + amzp_filmFade * 0.1;
            float fl = lum(fin);
            fin = mix(fin, float3(fl), amzp_filmFade * 0.2);
        }
        if (amzp_filmGrain > 0.00001) {
            float2 px = floor(getTexSize((screen.zw/1.0)) * uv);
            float n = noiseHash(px + time * 100.0) * 2.0 - 1.0;
            float fl = lum(fin);
            float grainMask = 1.0 - fl * 0.4;
            fin += n * amzp_filmGrain * 0.08 * grainMask;
        }
        if (amzp_ditherAmt > 0.00001) {
            float2 px = floor(getTexSize((screen.zw/1.0)) * uv);
            float n1 = fract(sin(dot(px, float2(12.9898, 78.233))) * 43758.5453);
            float n2 = fract(sin(dot(px, float2(24.123, 17.321))) * 12345.6789);
            float n3 = fract(sin(dot(px, float2(93.989, 67.345))) * 98765.4321);
            fin += (float3(n1, n2, n3) - 0.5) * amzp_ditherAmt;
        }
        fin = mix(baseRGB, fin, amzp_globalMix);
        fin = clamp(fin, 0.0, 1.0);
        amzOutput = float4(fin, src.a);
    }

half4 main(float2 coord) { amzCoord=coord*2.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

