            float3 diffGlow = mix(innerLin, outerLin, 0.5);
            float diffHL = smoothstep(0.3, 0.8, baseLum);
            diffGlow *= mix(1.0, diffHL, amzp_diffHighlights);
            totalGlow += diffGlow * amzp_diffAmount * 0.3;
        }
        totalGlow *= amzp_glowAmount;
        totalGlow = 1.0 - exp(-totalGlow * amzp_softClipKnee);
        float3 glowSRGB = linearToSrgb(max(totalGlow, 0.0));
        if ((amzp_glowOnly>0.5)) {
            amzOutput = float4(clamp(glowSRGB, 0.0, 1.0), 1.0);
            return;
        }
        float3 comp;
        float bm = float(int(amzp_blendMode));
        if (bm < 1.5) {
            comp = baseLin + srgbToLinear(max(glowSRGB, 0.0));
        } else if (bm < 2.5) {
            comp = srgbToLinear(1.0 - (1.0 - baseRGB) * (1.0 - clamp(glowSRGB, 0.0, 1.0)));
        } else if (bm < 3.5) {
            float3 gC = clamp(glowSRGB, 0.0, 1.0);
            float3 r;
            r.r = (gC.r<0.5) ? 2.0*baseRGB.r*gC.r+baseRGB.r*baseRGB.r*(1.0-2.0*gC.r) : 2.0*baseRGB.r*(1.0-gC.r)+sqrt(max(baseRGB.r,0.0))*(2.0*gC.r-1.0);
            r.g = (gC.g<0.5) ? 2.0*baseRGB.g*gC.g+baseRGB.g*baseRGB.g*(1.0-2.0*gC.g) : 2.0*baseRGB.g*(1.0-gC.g)+sqrt(max(baseRGB.g,0.0))*(2.0*gC.g-1.0);
            r.b = (gC.b<0.5) ? 2.0*baseRGB.b*gC.b+baseRGB.b*baseRGB.b*(1.0-2.0*gC.b) : 2.0*baseRGB.b*(1.0-gC.b)+sqrt(max(baseRGB.b,0.0))*(2.0*gC.b-1.0);
            comp = srgbToLinear(r);
        } else {
            comp = max(baseLin, srgbToLinear(max(glowSRGB, 0.0)));
        }
        float3 fin = linearToSrgb(max(comp, 0.0));
        if (abs(amzp_filmSaturation - 1.0) > 0.00001) {
            float fl = lum(fin);
            fin = mix(float3(fl), fin, amzp_filmSaturation);
        }
        if (abs(amzp_filmContrast) > 0.5) {
            float fc = amzp_filmContrast / 100.0;
            float fl = lum(fin);
            float sCurve = fl + fc * 0.5 * (fl - 0.5) * (1.0 - abs(fl - 0.5) * 2.0);
            float ratio = sCurve / max(fl, 0.00001);
            fin *= ratio;
        }
        if (abs(amzp_filmWarmth) > 0.00001) {
            fin.r += amzp_filmWarmth * 0.06;
            fin.b -= amzp_filmWarmth * 0.04;
        }
        if (amzp_filmFade > 0.00001) {
            fin = fin * (1.0 - amzp_filmFade * 0.15) + amzp_filmFade * 0.1;
            float fl = lum(fin);
            fin = mix(fin, float3(fl), amzp_filmFade * 0.2);
        }
        if (amzp_filmGrain > 0.00001) {
            float2 px = floor(getTexSize((screen.zw/1.0)) * uv);
            float n = noiseHash(px + time * 100.0) * 2.0 - 1.0;
            float fl = lum(fin);
            float grainMask = 1.0 - fl * 0.4;
            fin += n * amzp_filmGrain * 0.08 * grainMask;
        }
        if (amzp_ditherAmt > 0.00001) {
            float2 px = floor(getTexSize((screen.zw/1.0)) * uv);
            float n1 = fract(sin(dot(px, float2(12.9898, 78.233))) * 43758.5453);
            float n2 = fract(sin(dot(px, float2(24.123, 17.321))) * 12345.6789);
            float n3 = fract(sin(dot(px, float2(93.989, 67.345))) * 98765.4321);
            fin += (float3(n1, n2, n3) - 0.5) * amzp_ditherAmt;
        }
        fin = mix(baseRGB, fin, amzp_globalMix);
        fin = clamp(fin, 0.0, 1.0);
        amzOutput = float4(fin, src.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
